const accountNames={'Supervisor':'Agung Wijaya','Administrator':'Admin Cabang','Ni Putu Ayu':'Ni Putu Ayu','Kadek Putra':'Kadek Putra'};
function currentAccount(){let a=actor();return {name:accountNames[a]||a,role:a==='Supervisor'?'Supervisor Pemasaran':a==='Administrator'?'Administrator':'Account Officer',initials:(accountNames[a]||a).split(' ').map(n=>n[0]).slice(0,2).join('')}}
function openAccount(){let a=currentAccount();modal('Akun Anda',`<div class="accountprofile"><span class="profileinitials">${E(a.initials)}</span><div><strong>${E(a.name)}</strong><p>${E(a.role)}<br>Cabang Denpasar</p></div></div>`+select('Pengguna aktif','account',['Supervisor',...owners,'Administrator'],actor())+`<div class="accountlinks">${btn('Pengaturan workspace',"document.querySelector('#modal').close();go('Pengaturan')")}${btn('Informasi aplikasi',"document.querySelector('#modal').close();applicationInfo()")}</div>`,f=>{$('#role').value=f.account;backListState=null;resetLists();go(mobile?'Agenda':'Monitoring')})}
function applicationInfo(){modal('Informasi aplikasi',`<div class="facts">${labelled('Workspace','Cabang Denpasar')}${labelled('Zona waktu','Asia/Makassar (WITA)')}${labelled('Penyimpanan','Perangkat / browser ini')}${labelled('Koneksi sistem Bank','Belum dikonfigurasi')}</div><p class="hint">Data pada CMS dan mobile belum tersinkron. Status pengajuan berasal dari input manual pengguna.</p>`,()=>{})}
scaleBanner=function(){return ''};
function workspaceSettings(){let a=currentAccount();return titleBlock('Pengaturan','Akun, parameter kerja dan pengelolaan data.')+`<div class="settingsgrid"><section class="panel"><div class="accountprofile"><span class="profileinitials">${E(a.initials)}</span><div><h2>${E(a.name)}</h2><p>${E(a.role)}<br>Cabang Denpasar</p></div></div><div class="actions">${btn('Kelola akun','openAccount()')}${btn('Informasi aplikasi','applicationInfo()')}</div></section><section class="panel"><h2>Waktu dan batas tahap</h2>${stages.map(s=>`<div class="summaryrow"><b>${s}</b><span>${db.config.stageSla[s]} hari</span></div>`).join('')}<p>WITA · Hari kalender</p>${supervisors()?btn('Ubah parameter','configForm()'):''}</section><section class="panel"><h2>Impor dan ekspor</h2><p>Unduh salinan data atau impor file yang sudah disiapkan.</p><div class="actions">${btn('Ekspor data','exportData()')}<label class="button">Impor file<input hidden type="file" accept="application/json" onchange="importData(this)"></label></div></section>${supervisors()?`<section class="panel"><h2>Pengelolaan data</h2><p>Kelola data awal dan skenario kerja pada perangkat ini.</p><div class="actions">${btn('Pilih data kerja','scenarioDialog()')}${btn('Pulihkan data awal','resetDemo()')}</div></section>`:''}</div>`}
function mobileMore(){let a=currentAccount();return titleBlock('Workspace','Cabang Denpasar')+`<div class="panel"><div class="accountprofile"><span class="profileinitials">${E(a.initials)}</span><div><strong>${E(a.name)}</strong><p>${E(a.role)}</p></div></div></div><div class="panel"><div class="menulist">${[['Monitoring','Ringkasan progres dan prioritas'],['Persetujuan','Rencana dan perubahan kunjungan'],['Pengajuan','Nomor referensi dan status terbaru'],['Notifikasi','Pengingat dan eskalasi'],['Laporan','Hasil, referral dan export'],['Riwayat','Jejak perubahan data'],['Pengaturan','Akun dan preferensi kerja']].map(([p,s])=>`<button onclick="go('${p}')"><strong>${p}</strong><small>${s}</small><span>↗</span></button>`).join('')}</div></div>`}
function cleanStoredFixtures(){// Remove the illustrative seeded application, without changing user-entered applications.
 db.applications=db.applications.filter(a=>a.number!=='DEMO-APP-001');
 db.activities.forEach(a=>{if(a.note?.startsWith('Catatan simulasi riwayat aktivitas '))a.note=a.note.replace('Catatan simulasi riwayat aktivitas ','Hasil pertemuan dan tindak lanjut ')});
 db.tasks.forEach(t=>{if(t.location?.startsWith('Lokasi demo')){t.location='Lokasi input manual';t.locationSource='Manual'};(t.approvalHistory||[]).forEach(h=>{if(h.actor==='Data demo'){h.actor='Impor data';h.note='Rencana kunjungan awal'}})});
}
cleanStoredFixtures();
const contentBeforeWorkspace=renderContent;
renderContent=function(){if(view==='Pengaturan'){$('#app').innerHTML=workspaceSettings();return}if(view==='Lainnya'){$('#app').innerHTML=mobileMore();return}contentBeforeWorkspace();if(view==='Riwayat')$('#app').innerHTML=titleBlock('Riwayat perubahan','Telusuri aktivitas dan perubahan data dalam workspace.')+`<section class="panel">${history()}</section>`;};
const renderBeforeWorkspace=render;
render=function(){renderBeforeWorkspace();let a=currentAccount();$('#user').innerHTML=`<strong>${E(a.name)}</strong><small>${E(a.role)}</small>`;let avatar=document.querySelector('.accountbutton .avatar');if(avatar)avatar.textContent=a.initials;};
checkin=function(id){let t=task(id);try{guardVisit(t)}catch(e){return toast(e.message)}if(!isOpen(t))return toast('Aktivitas sudah ditutup.');if(t.checkin)return toast('Anda sudah check-in.');if(!navigator.geolocation)return toast('Aktifkan layanan lokasi untuk check-in.');toast('Mendapatkan lokasi…');navigator.geolocation.getCurrentPosition(p=>{t.checkin=now();t.status='Dikerjakan';t.location=`GPS: ${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)} · akurasi ${Math.round(p.coords.accuracy)} m`;t.locationSource='GPS';record('Check-in kunjungan',id,t.location);toast('Check-in berhasil')},()=>toast('Lokasi belum diperoleh. Periksa izin lokasi lalu coba kembali.'),{enableHighAccuracy:true,timeout:15000})};
scenarioDialog=function(){modal('Pilih data kerja',`<p>Data pada perangkat ini akan diganti. Ekspor salinan terlebih dahulu jika diperlukan.</p>`+select('Data kerja','size',['1.000 profil / 5.000 aktivitas','100 profil / 500 aktivitas','Data awal']),f=>{let d=f.size==='Data awal'?seed():makeLargeData(f.size.startsWith('1.000')?1000:100);try{localStorage.setItem(key,JSON.stringify(d))}catch(e){throw Error('Penyimpanan penuh. Pilih data kerja yang lebih kecil.')}db=d;migrate();cleanStoredFixtures();backListState=null;resetLists();go(mobile?'Agenda':'Monitoring')})};
const originalHistory=history;
history=function(id=''){let a=db.audit.filter(a=>!id||a.object===id).slice(0,50);return a.map(a=>`<div class="miniitem"><b>${E(a.action.replace(/prototype/gi,'workspace').replace(/demo/gi,'awal').replace(/simulasi/gi,'manual'))}</b><p>${E(a.detail)}</p><small>${fmt(a.time)} · ${E(a.actor==='Data demo'?'Impor data':a.actor)} · ${E(a.object)}</small></div>`).join('')||empty('Belum ada perubahan tercatat.')};

function localNow(){let p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()),v=k=>p.find(x=>x.type===k).value;return `${v('year')}-${v('month')}-${v('day')}T${v('hour')}:${v('minute')}`}
function toggleResultFields(){let f=$('#form');if(!f)return;let choice=f.elements.follow.value;for(let [id,show] of [['followFields',choice==='Tambah Task'],['waitFields',choice==='Menunggu dengan tanggal review'],['closeFields',choice==='Tutup opportunity']]){let e=document.getElementById(id);if(e){e.hidden=!show;for(let input of e.querySelectorAll('input,select,textarea'))input.disabled=!show}}}
activityForm=function(id){let t=task(id);if(!t||!mine(t)||!isOpen(t))return toast('Aktivitas tidak tersedia untuk diperbarui.');try{guardVisit(t)}catch(e){return toast(e.message)}if(activityKind(t.type)==='Kunjungan'&&(!t.checkin||!t.photo))return toast('Lengkapi check-in dan foto kunjungan terlebih dahulu.');let o=opp(t.opp);let followChoices=['Tambah Task','Menunggu dengan tanggal review'];if(o?.outcome==='Aktif')followChoices.push('Tutup opportunity');else followChoices.push('Tidak ada tindak lanjut');modal('Catat hasil '+t.type,select('Hasil','result',activityKind(t.type)==='Telepon'?['Tertarik','Tidak terhubung','Minta dihubungi kembali','Tidak tertarik','Nomor tidak valid']:['Terlaksana / bertemu','Tidak bertemu','Perlu dokumen tambahan','Kebutuhan berubah','Lainnya'])+area('Hasil dan kesepakatan','note','',true)+field('Waktu aktivitas (WITA)','occurred',localNow(),'datetime-local',true)+(activityKind(t.type)==='Meeting'?field('Peserta meeting','participants',t.participants||'','text',true)+area('Agenda meeting','meetingAgenda',t.meetingAgenda||'',true):'')+`<label>Langkah berikutnya<select name="follow" onchange="toggleResultFields()">${options(followChoices,followChoices[0])}</select></label><div id="followFields">`+field('Tujuan tindak lanjut','purpose')+select('Jenis aktivitas berikutnya','type',['Telepon','Kunjungan','Meeting','Cek dokumen'])+field('Jadwal tindak lanjut (WITA)','scheduled',dateOffset(2)+'T09:00','datetime-local')+field('Deadline tindak lanjut (WITA)','due',dateOffset(2)+'T17:00','datetime-local')+`</div><div id="waitFields" hidden>`+area('Menunggu apa / siapa?','waitReason')+field('Tanggal review (WITA)','review',dateOffset(2)+'T09:00','datetime-local')+`</div><div id="closeFields" hidden>`+select('Tahap penutup','closeStage',stageDefs().filter(s=>s.active&&s.type!=='process').map(s=>s.name))+area('Alasan / bukti hasil','closeReason')+field('Referensi kesepakatan','reference')+`</div>`,f=>{if(!isOpen(t))throw Error('Aktivitas ini sudah selesai.');if(f.follow==='Tambah Task'&&(!f.purpose?.trim()||!f.scheduled||!f.due))throw Error('Isi tujuan, jadwal dan deadline tindak lanjut.');if(f.follow==='Tambah Task'&&parseCRMDate(f.due)<parseCRMDate(f.scheduled))throw Error('Deadline mendahului jadwal tindak lanjut.');if(f.follow==='Menunggu dengan tanggal review'&&(!f.waitReason?.trim()||!f.review))throw Error('Isi alasan menunggu dan tanggal review.');if(f.follow==='Tutup opportunity'&&!f.closeReason?.trim())throw Error('Isi alasan atau bukti penutupan opportunity.');if(f.follow==='Tutup opportunity'&&o?.outcome!=='Aktif')throw Error('Opportunity sudah ditutup.');let a={id:uid('A'),task:t.id,profile:t.profile,opp:t.opp,lead:t.lead,type:t.type,result:f.result,note:f.note,occurred:f.occurred,recorded:now(),owner:t.owner,photo:t.photo,location:t.location,participants:f.participants||'',meetingAgenda:f.meetingAgenda||''};db.activities.unshift(a);t.status='Selesai';t.completed=now();if(activityKind(t.type)==='Kunjungan')t.checkout=now();if(f.follow==='Tambah Task'){let next={id:uid('T'),profile:t.profile,opp:t.opp,lead:t.lead,type:f.type,purpose:f.purpose,owner:t.owner,scheduled:f.scheduled,due:f.due,status:'Terjadwal'};if(activityKind(next.type)==='Kunjungan'){next.approval='Menunggu';next.approvalHistory=[{time:now(),actor:actor(),status:'Diajukan',note:'Tindak lanjut kunjungan'}]}db.tasks.push(next);a.nextTask=next.id;if(o){delete o.review;delete o.wait}}else if(f.follow==='Menunggu dengan tanggal review'){if(o){o.review=f.review;o.wait=f.waitReason}else{let next={id:uid('T'),profile:t.profile,lead:t.lead,type:'Cek dokumen',purpose:'Review: '+f.waitReason,owner:t.owner,scheduled:f.review,due:f.review,status:'Terjadwal'};db.tasks.push(next);a.nextTask=next.id}}else if(f.follow==='Tutup opportunity'){let cs=stageDefs().find(s=>s.name===f.closeStage);if(!cs||cs.type==='process')throw Error('Pilih tahap penutup.');o.stage=cs.name;o.stageId=cs.id;o.outcome=({won:'Won',lost:'Lost',cancelled:'Cancelled'})[cs.type];o.closed=now();o.reason=f.closeReason;o.reference=f.reference;nextTasks(o.id).forEach(x=>{x.status='Dibatalkan';x.cancelReason='Opportunity ditutup: '+f.closeReason});delete o.review;delete o.wait}record('Selesaikan aktivitas',t.id,f.result+' / '+f.follow)});toggleResultFields()};
function reopenRecord(kind,id){let x=kind==='lead'?db.leads.find(x=>x.id===id):opp(id);modal(kind==='lead'?'Aktifkan kembali lead':'Buka kembali opportunity',area('Alasan pembukaan kembali','reason','',true),f=>{if(kind==='lead'){if(x.status!=='Closed')throw Error('Lead tidak dalam status Closed.');x.status='In qualification'}else{if(x.outcome==='Aktif')throw Error('Opportunity masih aktif.');x.outcome='Aktif';x.entered=now();delete x.closed}record('Buka kembali '+kind,id,f.reason)})}
const workspaceDetailContent=renderContent;
renderContent=function(){workspaceDetailContent();if(view==='Lead detail'){let l=db.leads.find(x=>x.id===focus);if(l&&mine(l)&&l.status==='Closed')$('#app').insertAdjacentHTML('afterbegin',`<section class="closednotice">${badge('Closed')}<span>${E(l.reason||'Penjajakan ditutup')}</span>${btn('Aktifkan kembali',`reopenRecord('lead','${l.id}')`)}</section>`)}if(view==='Opportunity detail'){let o=opp(focus);if(o&&mine(o)&&o.outcome!=='Aktif')$('#app').insertAdjacentHTML('afterbegin',`<section class="closednotice">${badge(o.outcome)}<span>${E(o.reason||'Peluang ditutup')}</span>${btn('Buka kembali',`reopenRecord('opp','${o.id}')`)}</section>`)}if(view==='Aktivitas detail'){let t=task(focus),a=db.activities.find(a=>a.task===focus);if(t&&mine(t)&&a?.nextTask)$('#app').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Tindak lanjut berikutnya</h2>${taskCard(task(a.nextTask))}</section>`)}};


record=function(action,object,detail=''){let previous=localStorage.getItem(key);db.audit.unshift({id:uid('H'),action,object,detail,actor:actor(),time:now()});try{localStorage.setItem(key,JSON.stringify(db))}catch(e){if(previous){db=JSON.parse(previous);migrate();cleanStoredFixtures()}render();toast('Perubahan belum tersimpan. Ruang penyimpanan tidak mencukupi.');throw Error('Perubahan belum tersimpan. Kelola lampiran atau ekspor data, lalu coba kembali.')}render()};
addPhoto=function(id,input){let f=input.files?.[0];if(!f)return;if(!f.type.startsWith('image/'))return toast('Pilih file gambar.');if(f.size>1500000)return toast('Foto maksimal 1,5 MB.');let r=new FileReader();r.onerror=()=>toast('Foto gagal dibaca. Pilih ulang file.');r.onload=()=>{task(id).photo=r.result;try{record('Lampiran foto',id,f.name);toast('Foto ditambahkan')}catch(e){toast(e.message)}};r.readAsDataURL(f)};

const badgeBeforeNasabah=badge;badge=function(value){return badgeBeforeNasabah(value==='Customer'?'Nasabah':value==='Prospect'?'Lead':value)};
render();
